        let temp = TempDir::new().unwrap();
        let store = FeedbackStore::new(temp.path().join("feedback.jsonl"));

        for i in 0..5 {
            store
                .append(&FeedbackEntry::new(format!("entry {}", i)))
                .unwrap();
        }

